uint64_t em_string_to_64bit_int(const char* str) {
    // Ensure the string is exactly 8 characters
    if (strlen(str) != 8) {
        fprintf(stderr, "The input string must be exactly 8 characters long.\n");
        return 0;
    }

    // Create a 64-bit integer and copy the string bytes into it
    uint64_t int_value = 0;
    memcpy(&int_value, str, 8);

    // int_value = htonll(int_value);

    return int_value;
}

